import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { FiStar, FiClock, FiTrendingUp, FiTarget, FiUsers } from 'react-icons/fi';

const SuccessStories = () => {
  // Animation variants
  const fadeIn = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6 } }
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2
      }
    }
  };

  // Testimonial data
  const testimonials = [
    {
      name: "Sarah J.",
      quote: "GymFit's personalized approach helped me lose 15 pounds and build the strength I never thought possible. The AI adjusts as I progress, keeping my workouts challenging and effective.",
      role: "Premium Member, 8 months",
      rating: 5,
      achievement: "Lost 15 pounds",
      image: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?ixlib=rb-1.2.1&auto=format&fit=crop&w=256&q=80"
    },
    {
      name: "Michael T.",
      quote: "As someone with a busy schedule, I love how GymFit adapts to my availability. The nutrition guidance has been a game-changer for my energy levels and recovery.",
      role: "Premium Member, 1 year",
      rating: 5,
      achievement: "Improved energy and recovery",
      image: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-1.2.1&auto=format&fit=crop&w=256&q=80"
    },
    {
      name: "Emily R.",
      quote: "I've tried many fitness apps before, but GymFit is the only one that truly understands my needs. The AI personalization makes it feel like having a personal trainer in my pocket.",
      role: "Free Member, upgraded to Premium after 2 months",
      rating: 5,
      achievement: "Completed first 10K run",
      image: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?ixlib=rb-1.2.1&auto=format&fit=crop&w=256&q=80"
    },
    {
      name: "David L.",
      quote: "After my injury, I was hesitant to start exercising again. GymFit's adaptive workouts gradually built my confidence and strength back without risking re-injury.",
      role: "Premium Member, 6 months",
      rating: 5,
      achievement: "Recovered from injury",
      image: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?ixlib=rb-1.2.1&auto=format&fit=crop&w=256&q=80"
    },
    {
      name: "Jennifer K.",
      quote: "The community aspect of GymFit has been so motivating. Sharing achievements and tips with other members helps keep me accountable and inspired.",
      role: "Premium Member, 1.5 years",
      rating: 4,
      achievement: "Consistent 5-day workout streak for 6 months",
      image: "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?ixlib=rb-1.2.1&auto=format&fit=crop&w=256&q=80"
    },
    {
      name: "Carlos M.",
      quote: "As a beginner, fitness can be intimidating. GymFit made it approachable with clear guidance and gradually increasing challenges that built my confidence.",
      role: "Free Member, 4 months",
      rating: 5,
      achievement: "First pull-up achieved",
      image: "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-1.2.1&auto=format&fit=crop&w=256&q=80"
    }
  ];

  return (
    <div>
      {/* Hero Section */}
      <section className="bg-gradient-to-r from-indigo-600 to-primary text-white py-20">
        <div className="container-custom">
          <motion.div
            initial="hidden"
            animate="visible"
            variants={fadeIn}
            className="text-center"
          >
            <h1 className="text-4xl md:text-5xl font-bold mb-6">Success Stories</h1>
            <p className="text-xl max-w-3xl mx-auto">
              Real results from real people. See how GymFit has transformed the fitness journey of our members.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Success Metrics */}
      <section className="py-12 bg-white">
        <div className="container-custom">
          <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            variants={staggerContainer}
            className="grid grid-cols-1 md:grid-cols-4 gap-6 text-center"
          >
            {[
              { icon: <FiUsers size={32} />, stat: "10,000+", desc: "Active Members" },
              { icon: <FiClock size={32} />, stat: "25 min", desc: "Avg. Daily Workout" },
              { icon: <FiTrendingUp size={32} />, stat: "89%", desc: "Achieve Their Goals" },
              { icon: <FiTarget size={32} />, stat: "4.8/5", desc: "Member Satisfaction" }
            ].map((item, index) => (
              <motion.div
                key={index}
                variants={fadeIn}
                className="bg-gray-50 p-6 rounded-lg shadow-sm"
              >
                <div className="text-primary mb-4 flex justify-center">{item.icon}</div>
                <h3 className="text-3xl font-bold mb-2">{item.stat}</h3>
                <p className="text-gray-600">{item.desc}</p>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* Testimonials */}
      <section className="py-20 bg-gray-50">
        <div className="container-custom">
          <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            variants={staggerContainer}
            className="grid grid-cols-1 md:grid-cols-2 gap-8"
          >
            {testimonials.map((testimonial, index) => (
              <motion.div
                key={index}
                variants={fadeIn}
                className="bg-white p-8 rounded-lg shadow-md flex flex-col md:flex-row gap-6"
              >
                <div className="md:w-1/4 flex-shrink-0">
                  <img 
                    src={testimonial.image} 
                    alt={testimonial.name} 
                    className="w-20 h-20 rounded-full object-cover mx-auto"
                  />
                </div>
                <div className="md:w-3/4">
                  <div className="flex mb-2">
                    {[...Array(testimonial.rating)].map((_, i) => (
                      <FiStar key={i} className="text-yellow-400 fill-current" />
                    ))}
                  </div>
                  <div className="text-primary text-xl mb-4">"</div>
                  <p className="text-gray-700 mb-4 italic">{testimonial.quote}</p>
                  <div className="mt-auto">
                    <p className="font-bold">{testimonial.name}</p>
                    <p className="text-gray-500 text-sm mb-2">{testimonial.role}</p>
                    <div className="bg-green-100 text-green-800 text-xs font-medium px-2.5 py-0.5 rounded inline-flex items-center">
                      <FiTarget className="mr-1" />
                      {testimonial.achievement}
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-16 bg-gradient-to-r from-secondary to-green-500 text-white">
        <div className="container-custom text-center">
          <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            variants={fadeIn}
          >
            <h2 className="text-3xl font-bold mb-6">Ready to Write Your Success Story?</h2>
            <p className="text-xl mb-8 max-w-2xl mx-auto">
              Join GymFit today and start your journey to a healthier, stronger you.
            </p>
            <Link to="/services" className="bg-white text-secondary hover:bg-gray-100 font-bold py-3 px-8 rounded-md transition duration-300 inline-block">
              Get Started Now
            </Link>
          </motion.div>
        </div>
      </section>
    </div>
  );
};

export default SuccessStories;
